def distribution_chart(n_groups, points_per_group, shape_matters):
    if n_groups == 1:
        return "histogram"
    if shape_matters and points_per_group >= 30:
        return "violin"
    return "box"


for args in [(1, 200, True), (4, 240, True), (4, 10, True), (6, 100, False)]:
    print(distribution_chart(*args))
